  "pr.rates_esi": "মজুৰিৰ কৰ্মচাৰী 0.75% আৰু নিয়োগকৰ্তা 3.25%, প্ৰতিটো পিছৰ টকালৈ ৰাউণ্ড কৰা (Social Security (Central) Rules, 2026, rule 19)। মজুৰিৰ সীমা মাহে ₹21,000: বৰ্তমানৰ সীমা ESIC চাইটত চাওক। দৈনিক মজুৰি ₹176 বা তাতকৈ কম হ'লে কৰ্মচাৰীৰ অংশ নালাগে (ESIC contribution page)।",
