  "pr.pfintro": "মাহটোৰ দৰমহাৰ স্লিপবোৰৰ পৰা EPFO unified portal-ৰ বাবে ECR টেক্সট ফাইল আৰু চালানৰ টকা বনে। প্ৰথমে স্লিপবোৰ বনাওক (দৰমহা টেব); স্লিপ নথকা কৰ্মচাৰীসকলক তলত দেখুওৱা হৈছে।",
  "pr.unver_pf": "আপলোডৰ আগতে চাওক: এইটো বনোৱাৰ সময়ত (14 Nov 2026) EPFO-ৰ নিজৰ ফাইল-গঠনৰ নথিখন খুলিব পৰা নগ'ল। 11টা ফিল্ড আৰু সিহঁতৰ ক্ৰম পেৰ'ল ছফ্টৱেৰ নিৰ্মাতাসকলে প্ৰকাশ কৰাৰ দৰে। ফাইলটো EPFO পৰ্টেলৰ ECR পেজত আপলোড কৰক; পৰ্টেলে কোনো শাৰী নাকচ কৰিলে কাৰণ কয়।",
