  "pr.esiintro": "মাহটোৰ দৰমহাৰ স্লিপবোৰৰ পৰা ESIC employer portal-ৰ বাবে মাহিলী কন্ট্ৰিবিউচন শ্বীট আৰু চালানৰ টকা বনে। কেৱল মজুৰিৰ সীমাৰ ভিতৰত থকা (বা একে আধা বছৰত আগতে সামৰি লোৱা) কৰ্মচাৰীসকলক ফাইলত দেখুওৱা হয়।",
  "pr.unver_esi": "এই শ্বীটখন ESIC পৰ্টেলৰ নিজৰ Monthly Contribution টেমপ্লেট অনুসৰি (15 Nov 2026 ত চোৱা): ছটা টেক্সট কলাম, Excel 97-2003 (.xls) হিচাপে ছেভ কৰা। এই মাহত মজুৰি নোপোৱা কৰ্মচাৰীসকলকো কাৰণ ক'ডৰ সৈতে দেখুওৱা হয়। প্ৰথমে এমাহৰ আপলোড কৰি পৰ্টেলৰ ফলাফল চাওক।",
