  "it.f_def_h": "কেপিটেল গেইন, জিকা ধন, ডিভিডেণ্ড বা ব্যৱসায়ৰ প্ৰথম বছৰৰ লাভ যিটো আপুনি এতিয়াও উপাৰ্জন কৰা নাই: বাকী কিস্তিত দিলে আগৰ কিস্তিৰ বাবে গণ্য নহয় (section 425(4))।",
