  "it.basis": "এই অংকবোৰ কিহৰ ওপৰত ভিত্তি কৰি ({d} ত)",
  "it.b1": "দৰ ({d} ত), কৰ বছৰ 2026-27: নতুন ৰেজিম ₹4 লাখলৈকে শূন্য, ₹8 লাখলৈকে 5%, ₹12 লাখলৈকে 10%, ₹16 লাখলৈকে 15%, ₹20 লাখলৈকে 20%, ₹24 লাখলৈকে 25%, তাতকৈ বেছিত 30%; ₹12 লাখলৈকে আয়ত কৰ নালাগে বুলি ৰিবেট, ঠিক তাৰ ওপৰত মাৰ্জিনেল ৰিলিফ; দৰমহাত ষ্টেণ্ডাৰ্ড ডিডাকচন ₹75,000। পুৰণি ৰেজিম: ₹2.5 লাখলৈকে শূন্য (60 বছৰত ₹3 লাখ, 80 বছৰত ₹5 লাখ), ₹5 লাখলৈকে 5%, ₹10 লাখলৈকে 20%, তাতকৈ বেছিত 30%; ₹5 লাখলৈকে ₹12,500 ৰিবেট; ষ্টেণ্ডাৰ্ড ডিডাকচন ₹50,000। এইবোৰ দৰমহাৰ স্লিপ টুলে আগৰে পৰা ব্যৱহাৰ কৰা দৰ; এই বিল্ডত Finance Act ৰ পৰা আকৌ পঢ়া হোৱা নাই, সেয়েহে নিশ্চিত কৰক।",
  "it.b2": "এডভান্স টেক্স (Income-tax Act 2025, sections 403 ৰ পৰা 408): TDS-ৰ পিছত কৰ ₹10,000 বা তাতকৈ বেছি হ'লে লাগে; 15 June ৰ ভিতৰত 15%, 15 September ৰ ভিতৰত 45%, 15 December ৰ ভিতৰত 75%, 15 March ৰ ভিতৰত সকলো; প্ৰেজাম্পটিভ কৰদাতাই 15 March ৰ ভিতৰত সকলো দিয়ে; 31 March লৈকে দিয়া পেমেণ্ট বছৰটোৰ বাবে গণ্য হয়; ব্যৱসায়ৰ আয় নথকা 60 বছৰ বা তাতকৈ বেছি বয়সৰ বাসিন্দা ৰেহাই পায়।",
  "it.b3": "সুদ: কৰৰ 90%-তকৈ কম দিলে কম দিয়াখিনিত section 424 (পুৰণি 234B) মাহে বা মাহৰ অংশত 1%; section 425 (পুৰণি 234C) প্ৰথম তিনিটা কিস্তিৰ প্ৰতিটোৰ কম দিয়াখিনিত 3% (15 June ৰ ভিতৰত 12% আৰু 15 September ৰ ভিতৰত 36% দিলে নালাগে) আৰু March ৰ কম দিয়াখিনিত 1%।",
  "it.b4": "ওপৰৰ চেকশ্বনবোৰ 15 Nov 2026 ত Income Tax Department ৰ ৱেবচাইটৰ (incometaxindia.gov.in) অফিচিয়েল টেক্সটৰ সৈতে শব্দে শব্দে মিলোৱা হৈছিল। প্ৰিণ্ট কৰা Act-এ চূড়ান্ত।",
  "it.b5": "হিচাপৰ লাভ কৰযোগ্য লাভ নহয়: Act অনুসৰি ডেপ্ৰিচিয়েচন, অনুমতি নোপোৱা খৰচ আৰু প্ৰেজাম্পটিভ নিয়মে ইয়াক সলনি কৰে। এই প্লেন আৰু ডেটা শ্বীট আপোনাৰ একাউণ্টেণ্টক দিয়ক।",
  "it.b6": "হিচাপ কৰা নহয়: চাৰ্চাৰ্জ, বিশেষ দৰৰ কেপিটেল গেইন, বিদেশী কৰৰ ৰিলিফ, নাবালকৰ আয়ৰ কৰ, আৰু পলমকৈ ফাইল কৰাৰ সুদ।",
  "it.b7": "একো ফাইল কৰা নহয় আৰু আপোনাৰ হিচাপত একো লিখা নহয়।",
  "it.itr_h": "কোনখন ৰিটাৰ্ন ফৰ্ম মিলে, কিয়, আৰু কি কি কাগজ সাজু ৰাখিব চাবলৈ কেইটামান প্ৰশ্নৰ উত্তৰ দিয়ক।",
