  "it.n_forms": "চৰ্তবোৰ 31 March 2026 ত শেষ হোৱা বছৰৰ বাবে জাননী দিয়া ৰিটাৰ্ন অনুসৰি (টেক্স পৰ্টেলবোৰৰ মতে, ITR-1 আৰু ITR-4 ত এতিয়া দুটালৈকে ঘৰ-সম্পত্তি চলে)। কৰ বছৰ 2026-27 ৰ ৰিটাৰ্ন Income-tax Rules, 2026 ৰ অধীনত এতিয়াও জাননী দিয়া হোৱা নাই: ফাইল কৰাৰ আগতে কোনে ব্যৱহাৰ কৰিব নোৱাৰে তাৰ ফৰ্মৰ নিজৰ তালিকা পঢ়ক।",
