  "ca.intro": "এটা ব্যৱসায় আৰু সময়সীমা এটা কেৱল-পঢ়িবলৈ ফাইলত (.nsca) ভৰায়। ইয়াক WhatsApp বা ইমেইলত আপোনাৰ একাউণ্টেণ্টলৈ পঠিয়াওক। তেওঁ ca.niveshsahayak.in ত খোলে, হিচাপ পঢ়ে, প্ৰশ্ন যোগ কৰে আৰু আপোনালৈ মন্তব্য ঘূৰাই পঠিয়ায়।",
  "ca.notlive": "এইটো ফাইল দিয়া-লোৱা, লাইভ শ্বেয়াৰ কৰা লগইন নহয়। ফাইল বনোৱাৰ সময়ত হিচাপ যিদৰে আছিল, আপোনাৰ একাউণ্টেণ্টে সেইদৰে দেখে। লাইভ লগইনৰ বাবে আপোনাৰ হিচাপ ৰখা চাৰ্ভাৰ লাগিব, আৰু Nivesh Sahayak-ৰ তেনে নাই: আপোনাৰ হিচাপ আপোনাৰ ডিভাইচতে থাকে। নতুন এণ্ট্ৰীৰ বাবে নতুন ফাইল বনাওক।",
