  "ca.cT": "CA-ৰ মন্তব্য",
  "ca.cIntro": "আপোনাৰ একাউণ্টেণ্টে প্ৰশ্ন আৰু মন্তব্যৰ এটা সৰু ফাইল (.nsca-comments) ঘূৰাই পঠিয়ায়। প্ৰতিটো প্ৰশ্ন সংশ্লিষ্ট এণ্ট্ৰীৰ কাষত চাবলৈ ইয়াত লোড কৰক। উত্তৰ দিয়ক, বন্ধ বুলি চিহ্ন দিয়ক, আৰু ঘূৰাই পঠিয়াবলৈ ফাইলটো আকৌ ছেভ কৰক।",
