  "cv.h1": "একাউণ্টেণ্ট ভিউৱাৰ: আপোনাৰ ক্লায়েণ্টে পঠিওৱা হিচাপৰ ফাইল খোলক",
  "cv.intro": "আপোনাৰ ক্লায়েণ্টে এটা সময়সীমাৰ হিচাপ এটা ফাইলত ভৰাই WhatsApp বা ইমেইলত আপোনালৈ পঠিয়ায়। ইয়াত খুলি পঢ়ক: বাকী, পাৰ্টী, লেজাৰ, ডে বুক, GST হিচাপ, ফাইনেল একাউণ্ট আৰু প্ৰতিখন ডকুমেণ্ট। বিচাৰক আৰু ফিল্টাৰ কৰক, যিকোনো এণ্ট্ৰীত প্ৰশ্ন কৰক, আৰু আপোনাৰ মন্তব্য এটা সৰু ফাইল হিচাপে ঘূৰাই পঠিয়াওক। ফ্ৰী, লগইন নালাগে, আৰু একো আপলোড নহয়: ফাইলটো আপোনাৰ ব্ৰাউজাৰৰ ভিতৰতে পঢ়া হয়।",
  "cv.drop": ".nsca ফাইলটো ইয়াত এৰি দিয়ক",
  "cv.choose": "ফাইল বাছক",
  "cv.dropnote": "ফাইলটো এই ডিভাইচতে থাকে। ইয়াত একো ছেভ নহয় আৰু ইয়াৰ পৰা আপুনি ক্লায়েণ্টৰ হিচাপ সলনি কৰিব নোৱাৰে।",
  "cv.nav.home": "সাৰাংশ",
  "cv.docs": "ডকুমেণ্ট",
  "cv.day": "ডে বুক",
  "cv.fin": "ফাইনেল একাউণ্ট",
  "cv.gst": "GST হিচাপ",
  "cv.cT": "প্ৰশ্ন আৰু মন্তব্য",
  "cv.how.h": "ই কেনেকৈ কাম কৰে",
  "cv.how.1": "আপোনাৰ ক্লায়েণ্টে Nivesh Sahayak খোলে, মোৰ ডেটা, একাউণ্টেণ্টলৈ পঠিয়াওকলৈ যায়, আৰু এটা ব্যৱসায় আৰু সময়সীমাৰ বাবে \"মোৰ একাউণ্টেণ্টৰ বাবে এটা ফাইল বনাওক\" বাছে।",
  "cv.how.2": "তেওঁ আপোনালৈ ফাইলটো (.nsca ৰে শেষ হোৱা) আৰু একেটা মেছেজত এটা চুটি চেক ক'ড পঠিয়ায়।",
  "cv.how.3": "আপুনি এই পেজত ফাইলটো খোলে। পেজে ফাইলটো সলনি নোহোৱাকৈ আছে নে নাই কয় আৰু মিলাবলৈ ক্লায়েণ্টে দিয়া চেক ক'ড লিখিবলৈ দিয়ে।",
  "cv.how.4": "হিচাপ পঢ়ক, বিচাৰক, আৰু যিকোনো ডকুমেণ্ট, ডে-বুক এণ্ট্ৰী বা স্ক্ৰীণত \"প্ৰশ্ন বা মন্তব্য যোগ কৰক\" টিপক। আপুনি লিখা সকলো এই ব্ৰাউজাৰতে থাকে।",
  "cv.how.5": "শেষ হ'লে \"প্ৰশ্ন আৰু মন্তব্য\" খোলক আৰু সৰু .nsca-comments ফাইলটো ঘূৰাই পঠিয়াওক। আপোনাৰ ক্লায়েণ্টে লোড কৰে আৰু প্ৰতিটো প্ৰশ্ন এণ্ট্ৰীৰ কাষত দেখে। তেওঁ উত্তৰ দিব পাৰে, আৰু আপুনি উত্তৰবোৰ ইয়াত লোড কৰিব পাৰে।",
  "cv.live.h": "ফাইল দিয়া-লোৱা, লাইভ লগইন নহয়",
  "cv.live.p": "এইটো ফাইল দিয়া-লোৱা। আপুনি ক্লায়েণ্টৰ একাউণ্টত লগইন নকৰে আৰু তেওঁ পিছত কৰা সলনিবোৰ নেদেখে। লাইভ শ্বেয়াৰ কৰা লগইনৰ বাবে হিচাপ ৰখা চাৰ্ভাৰ লাগিব, আৰু Nivesh Sahayak-ৰ তেনে নাই: হিচাপ ক্লায়েণ্টৰ ডিভাইচতে থাকে। নতুন সময়সীমা বা শুধৰণিৰ পিছত ক্লায়েণ্টৰ পৰা নতুন ফাইল বিচাৰক।",
  "cv.safe.h": "ফাইলত কি আছে, আৰু কি নাই",
  "cv.safe.p": "কি ভিতৰত যাব আপোনাৰ ক্লায়েণ্টে টিক দিয়ে। সাধাৰণতে ফাইলত সময়সীমাৰ শেষলৈকে এটা ব্যৱসায়ৰ এণ্ট্ৰী, পাৰ্টী আৰু আইটেম থাকে। কোটেশ্বন আৰু অৰ্ডাৰ, দৰমহা আৰু কৰ্মচাৰীৰ ৰেকৰ্ড, ফোন নম্বৰ আৰু ই-মেইল ঠিকনা, আৰু ব্যৱসায়ৰ বেংক একাউণ্টৰ বিৱৰণ ক্লায়েণ্টে টিক নিদিলে বাদ পৰে। ছবি, PIN আৰু বেকআপৰ ছেটিং কেতিয়াও নাথাকে। ফাইলত চেকচাম থাকে যাতে ইয়াৰ যিকোনো সলনি এই পেজত দেখা যায়। ফাইল সলনি কৰি চেকচাম আকৌ হিচাপ কৰাজনক চেকচামে ৰখিব নোৱাৰে, সেয়েহে ক্লায়েণ্টে বেলেগকৈ পঠিওৱা চেক ক'ডৰ সৈতে মিলাওক।",
  "cv.readonly": "এইটো এটা ফাইলৰ কেৱল-পঢ়িবলৈ ভিউ: ইয়াত একো সলনি বা ছেভ কৰিব নোৱাৰি।",
  "cv.notfile": "এইটো Nivesh Sahayak একাউণ্টেণ্ট ফাইল (.nsca) নহয়।",
  "cv.iscomments": "এইটো মন্তব্যৰ ফাইল। প্ৰথমে হিচাপৰ ফাইল (.nsca) খোলক, তাৰ পিছত \"প্ৰশ্ন আৰু মন্তব্য\"ৰ পৰা মন্তব্য লোড কৰক।",
  "cv.newer": "এই ফাইলটো নতুন ভাৰ্চনে বনাইছে। পেজটো ৰিল'ড কৰি আকৌ চেষ্টা কৰক।",
  "cv.nostore": "আপোনাৰ মন্তব্য এই ব্ৰাউজাৰত ৰাখিব পৰা নগ'ল। এতিয়াই মন্তব্যৰ ফাইল ছেভ কৰক।",
