  "cm.h.unit": "কোনে লোন লৈছে আৰু কিহৰ বাবে। এই বিৱৰণ প্ৰজেক্ট ৰিপ'ৰ্টত যায়। সকলো এই ডিভাইচতে থাকে।",
  "cm.h.figs": "প্ৰতি বছৰৰ অংক {u}ত লিখক, বেলেঞ্চ শ্বীট আৰু প্ৰফিট এণ্ড লছ একাউণ্টত থকাৰ দৰে। পিছৰ বছৰবোৰ: অডিট কৰা বা ফাইল কৰা একাউণ্টৰ পৰা। শেষৰ শাৰীত লায়েবিলিটি আৰু এছেটৰ পাৰ্থক্য দেখুৱায়: ই শূন্য হ'ব লাগিব।",
  "cm.h.proj": "প্ৰজেক্টেড বছৰবোৰ শেষৰ একচুৱেল বা এষ্টিমেট বছৰৰ পৰা হিচাপ কৰা হয়: আপুনি দিয়া হাৰত ছেল বাঢ়ে, প্ৰতিটো খৰচে ছেলৰ নিজৰ অংশ ৰাখে, ষ্টক আৰু ডেবটৰে নিজৰ দিন ৰাখে, নতুন লোনে নিজৰ চিডিউল মানে, আৰু কেশ হৈছে বেলেঞ্চিং অংক। পিছত অংক টেবত যিকোনো প্ৰজেক্টেড অংক হাতেৰে সলনি কৰক।",
