  "au.h.client": "প্ৰতি ক্লায়েণ্ট আৰু বছৰৰ বাবে এটা ফাইল। আপোনাৰ নিজৰ ফাৰ্মৰ বিৱৰণ এই ডিভাইচত এবাৰ ৰখা হয় আৰু প্ৰতিখন চাৰ্টিফিকেটত যায়।",
  "au.h.fa": "প্ৰতিটো এছেট এবাৰ লিখক। ৰেজিষ্টাৰে {y}ৰ ডেপ্ৰিচিয়েশ্বন কোম্পানী আইনৰ Schedule II আৰু ইনকাম টেক্সৰ ব্লক অনুসৰি হিচাপ কৰে, আৰু পাৰ্থক্যৰ ওপৰত ডেফাৰ্ড টেক্স। পিছৰ বছৰ আৰম্ভ কৰিলে শেষৰ অংকবোৰ আগবঢ়াই নিয়ে।",
  "au.h.cf": "প্ৰফিট এণ্ড লছ একাউণ্ট আৰু দুয়োখন বেলেঞ্চ শ্বীটৰ অংক লিখক। ষ্টেটমেণ্ট ইনডাইৰেক্ট পদ্ধতিৰে হিচাপ কৰা হয় আৰু আৰম্ভণি আৰু শেষৰ কেশৰ সৈতে মিলাই চোৱা হয়।",
  "au.h.ratio": "এই বছৰ আৰু যোৱা বছৰৰ অংক লিখক। Schedule IIIয়ে বিচৰা এঘাৰটা ৰেছিঅ' সলনিৰ সৈতে হিচাপ কৰা হয়, আৰু সলনি 25%ৰ ওপৰত হ'লে চিন দিয়া হয়।",
  "au.h.caro": "প্ৰথমে চাওক অৰ্ডাৰটো প্ৰযোজ্য হয় নে নহয়। তাৰ পিছত প্ৰতিটো ক্লজ চিন দিয়ক, আপোনাৰ মন্তব্য আৰু ৱৰ্কিং পেপাৰ লিখক, আৰু ফাইলৰ বাবে চেকলিষ্ট প্ৰিণ্ট কৰক।",
  "au.h.cert": "চাৰ্টিফিকেট বা চিঠি বাছক, বাকচবোৰ পূৰণ কৰক আৰু প্ৰিণ্ট কৰক। তালিকাৰ শাৰীবোৰ এটা শাৰীত এটাকৈ লিখক, বিৱৰণ আৰু টকাৰ মাজত | দি।",
