  "ix.h.match": "বাওঁফালে ষ্টেটমেণ্টৰ TDS অংশ পেষ্ট কৰক বা খোলক (Annual Information Statement, বা টেক্স বছৰ 2026-27ৰ পৰা Form 168, পুৰণি 26AS) আৰু সোঁফালে ক্লায়েণ্টৰ লেজাৰ। কোনটো কলাম কি বাছক। প্ৰতিজন ডিডাক্টৰৰ যোগফল দুয়োফালে কৰি মিলাই চোৱা হয়।",
