  "tf.src": "19 নৱেম্বৰ 2026ত Income-tax Act 2025 আৰু Income-tax Rules 2026 (G.S.R. 198(E), 20 মাৰ্চ 2026)ৰ সৈতে মিলাই চোৱা হৈছে। বিলত TDS হিচাপ কৰোঁতে NSBiz য়েও এই একেটা টেবুল ব্যৱহাৰ কৰে।",
