  "gb.lead": "কি কিনা হৈছিল বাছক। চেকাৰে কয় CGST আইনৰ section 17(5) অনুসৰি ইনপুট টেক্স ক্ৰেডিট ব্লক নেকি, আৰু কোনবোৰ ব্যতিক্ৰমত আপুনি দাবী কৰিব পাৰে।",
